<?php
declare(strict_types=1);
$config = require dirname(__DIR__, 2) . '/parser/config.php';
function readJson(string $path): array { $data = is_file($path) ? json_decode((string)file_get_contents($path), true) : []; return is_array($data) ? $data : []; }
function writeJson(string $path, array $data): void { $tmp = $path . '.tmp'; file_put_contents($tmp, json_encode($data, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT) . PHP_EOL, LOCK_EX); rename($tmp, $path); }
$city = $_GET['city'] ?? 'novosibirsk'; if (!isset($config['cities'][$city])) $city = 'novosibirsk';
$notice = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $city = $_POST['city'] ?? $city;
    if (isset($_POST['update_now'])) { $output = []; $code = 0; exec(PHP_BINARY . ' ' . escapeshellarg(dirname(__DIR__, 2) . '/parser/update-tariffs.php') . ' 2>&1', $output, $code); $notice = $code === 0 ? implode("\n", $output) : 'Обновление завершилось с ошибкой: ' . implode("\n", $output); }
    elseif (isset($_POST['reset_field'])) { $overrides = readJson($config['paths']['overrides'] . '/' . $city . '.json'); unset($overrides[$_POST['id']][$_POST['field']]); if (empty($overrides[$_POST['id']])) unset($overrides[$_POST['id']]); writeJson($config['paths']['overrides'] . '/' . $city . '.json', $overrides); $notice = 'Автоматическое значение восстановлено.'; }
    elseif (isset($_POST['save'])) { $overrides = readJson($config['paths']['overrides'] . '/' . $city . '.json'); $id = $_POST['id']; $overrides[$id] = array_filter(['name' => trim($_POST['name']), 'price' => (int)$_POST['price'], 'speed' => (int)$_POST['speed'], 'tv_channels' => $_POST['tv_channels'] === '' ? null : (int)$_POST['tv_channels'], 'connection_price' => $_POST['connection_price'] === '' ? null : (int)$_POST['connection_price'], 'category' => $_POST['category'], 'badge' => trim($_POST['badge']), 'sort' => (int)$_POST['sort'], 'active' => isset($_POST['active'])], fn($value) => $value !== ''); writeJson($config['paths']['overrides'] . '/' . $city . '.json', $overrides); $notice = 'Изменения сохранены и будут иметь приоритет при следующем импорте.'; }
    elseif (isset($_POST['add_manual'])) { $manual = readJson($config['paths']['manual'] . '/' . $city . '.json'); $id = 'manual-' . $city . '-' . preg_replace('/[^a-z0-9]+/', '-', strtolower(trim($_POST['name']))) . '-' . time(); $manual[] = ['id' => $id, 'source' => 'manual', 'city' => $city, 'category' => $_POST['category'], 'name' => trim($_POST['name']), 'speed' => (int)$_POST['speed'], 'price' => (int)$_POST['price'], 'connection_price' => (int)$_POST['connection_price'], 'router' => trim($_POST['router']), 'active' => true, 'sort' => (int)$_POST['sort']]; writeJson($config['paths']['manual'] . '/' . $city . '.json', $manual); $notice = 'Ручной тариф добавлен. Нажмите «Обновить тарифы сейчас», чтобы собрать итоговый JSON.'; }
    elseif (isset($_POST['delete_manual'])) { $manual = array_values(array_filter(readJson($config['paths']['manual'] . '/' . $city . '.json'), fn($tariff) => $tariff['id'] !== $_POST['id'])); writeJson($config['paths']['manual'] . '/' . $city . '.json', $manual); $notice = 'Ручной тариф удалён. Нажмите «Обновить тарифы сейчас», чтобы собрать итоговый JSON.'; }
}
$tariffs = readJson($config['paths']['final'] . '/' . $city . '.json'); $overrides = readJson($config['paths']['overrides'] . '/' . $city . '.json');
?><!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Тарифы — администрирование</title><style>body{margin:32px;font:15px Arial;color:#151b2b;background:#f5f7fa}main{max-width:1100px;margin:auto}form,article{background:#fff;padding:18px;border-radius:10px;margin:12px 0}select,input,button{padding:8px;margin:4px}input{max-width:170px}button{cursor:pointer}.notice{white-space:pre-line;background:#e7f8ec;padding:12px;border-radius:8px}small{color:#687083}</style><main><h1>Тарифы</h1><?php if ($notice): ?><p class="notice"><?= htmlspecialchars($notice) ?></p><?php endif ?><form method="get"><label>Город <select name="city"><?php foreach ($config['cities'] as $slug => $definition): ?><option value="<?= $slug ?>" <?= $slug === $city ? 'selected' : '' ?>><?= htmlspecialchars($definition['name']) ?></option><?php endforeach ?></select></label><button>Показать</button></form><form method="post"><input type="hidden" name="city" value="<?= $city ?>"><button name="update_now">Обновить тарифы сейчас</button></form><form method="post"><input type="hidden" name="city" value="<?= $city ?>"><strong>Добавить ручной тариф</strong><br><input name="name" required placeholder="Название"><input name="price" type="number" required placeholder="Цена"><input name="speed" type="number" required placeholder="Скорость"><input name="connection_price" type="number" value="0" placeholder="Подключение"><input name="router" placeholder="Оборудование"><select name="category"><option value="internet">Интернет</option><option value="internet_tv">Интернет + ТВ</option></select><input name="sort" type="number" value="100" placeholder="Сортировка"><button name="add_manual">Добавить</button></form><?php foreach ($tariffs as $tariff): $override = $overrides[$tariff['id']] ?? []; ?><article><form method="post"><input type="hidden" name="city" value="<?= $city ?>"><input type="hidden" name="id" value="<?= htmlspecialchars($tariff['id']) ?>"><strong><?= htmlspecialchars($tariff['id']) ?></strong> <small><?= ($tariff['source'] ?? '') === 'manual' ? 'Ручной тариф' : (isset($override['price']) ? 'Цена: вручную' : 'Цена: авто') ?></small><br><input name="name" value="<?= htmlspecialchars($tariff['name']) ?>" placeholder="Название"><input name="price" type="number" value="<?= (int)$tariff['price'] ?>" placeholder="Цена"><input name="speed" type="number" value="<?= (int)($tariff['speed'] ?? 0) ?>" placeholder="Скорость"><input name="tv_channels" type="number" value="<?= htmlspecialchars((string)($tariff['tv_channels'] ?? '')) ?>" placeholder="ТВ-каналы"><input name="connection_price" type="number" value="<?= htmlspecialchars((string)($tariff['connection_price'] ?? '')) ?>" placeholder="Подключение"><select name="category"><option value="internet" <?= $tariff['category'] === 'internet' ? 'selected' : '' ?>>Интернет</option><option value="internet_tv" <?= $tariff['category'] === 'internet_tv' ? 'selected' : '' ?>>Интернет + ТВ</option></select><input name="badge" value="<?= htmlspecialchars($tariff['badge'] ?? '') ?>" placeholder="Бейдж"><input name="sort" type="number" value="<?= (int)($tariff['sort'] ?? 0) ?>" placeholder="Сортировка"><label><input name="active" type="checkbox" <?= ($tariff['active'] ?? true) ? 'checked' : '' ?>> Показывать</label><button name="save">Сохранить</button><?php if (($tariff['source'] ?? '') === 'manual'): ?><button name="delete_manual">Удалить ручной</button><?php endif ?><?php foreach (array_keys($override) as $field): ?><button name="reset_field" value="1" formaction="?city=<?= $city ?>" onclick="this.form.field.value='<?= $field ?>'">Вернуть авто: <?= $field ?></button><?php endforeach ?><input type="hidden" name="field"></form></article><?php endforeach ?></main></html>
